> + basegfx::B2DHomMatrix aInverse(aTransform);
> + CPPUNIT_ASSERT(aInverse.invert());
> + const basegfx::B2DPoint aTextPosition(
> + aInverse
> + * basegfx::B2DPoint(getXPath(pXmlDoc, "//textsimpleportion", "x").toDouble(),
> + getXPath(pXmlDoc, "//textsimpleportion", "y").toDouble()));
> + // Compare in the shape's unrotated coordinates, using the actual text advance
> + // rather than platform-dependent font metrics. Counting one line is not enough.
> + CPPUNIT_ASSERT_DOUBLES_EQUAL(
> + fWidth * aAlignment[i],
